using SonrisaNews.Domain;

namespace SonrisaNews.Domain.Entities;

/// <summary>
/// A user's connection to an external destination (an email inbox, a Slack
/// webhook, etc.). Notifications are routed through channels; a channel must
/// be <see cref="Verified"/> before the dispatcher will send to it.
/// </summary>
/// <remarks>
/// <see cref="QuietHoursStart"/> and <see cref="QuietHoursEnd"/> are nullable
/// local-time <see cref="TimeOnly"/> values — null means "no quiet hours",
/// which is the MVP default per <c>1-features.md</c> §2.4. The values are
/// stored as <c>TIME</c> in SQLite/Postgres and interpreted in the user's
/// <c>User.TimeZone</c>.
/// </remarks>
public class Channel
{
    public Guid Id { get; set; }

    public Guid UserId { get; set; }

    public ChannelType Type { get; set; }

    /// <summary>The address the user entered (e.g. <c>ada@example.com</c> or a Slack incoming-webhook URL).</summary>
    public string Destination { get; set; } = string.Empty;

    /// <summary>Set to true only after the user has completed the verification flow for this destination.</summary>
    public bool Verified { get; set; }

    /// <summary>Local-time start of the quiet window. Null = no quiet hours.</summary>
    public TimeOnly? QuietHoursStart { get; set; }

    /// <summary>Local-time end of the quiet window. May wrap past midnight (e.g. 22:00–07:00).</summary>
    public TimeOnly? QuietHoursEnd { get; set; }

    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;
}

using SonrisaNews.Domain;

namespace SonrisaNews.Domain.Entities;

/// <summary>
/// A raw upstream event (an RSS item, a USGS earthquake feed entry, a yfinance
/// quote). Dedupe is on <c>(SourceId, ExternalId)</c>; the matcher window
/// query is the composite index on <c>(SourceId, OccurredAt)</c>.
/// </summary>
/// <remarks>
/// <see cref="Type"/> reuses <see cref="AlertType"/>: a News alert matches a
/// News event, a Market alert matches a Market event, a Disaster alert matches
/// a Disaster event. The values are spelled out in the matcher contract
/// (<c>docs/implementation/mvp-checklist.md</c> §2 wave 6).
/// </remarks>
public class Event
{
    public Guid Id { get; set; }

    public Guid SourceId { get; set; }

    /// <summary>The upstream-assigned identifier (RSS <c>&lt;guid&gt;</c>, USGS event id, ticker + timestamp). Unique per source.</summary>
    public string ExternalId { get; set; } = string.Empty;

    public AlertType Type { get; set; }

    /// <summary>Raw upstream payload as a JSON string. Stored as <c>TEXT</c> on SQLite, <c>jsonb</c> on Postgres.</summary>
    public string Payload { get; set; } = "{}";

    /// <summary>UTC time the upstream reported the event happening.</summary>
    public DateTimeOffset OccurredAt { get; set; }

    /// <summary>UTC time our poller persisted the row. Used for the 30-day retention cutoff.</summary>
    public DateTimeOffset FetchedAt { get; set; } = DateTimeOffset.UtcNow;
}

namespace SonrisaNews.Domain.Entities;

/// <summary>
/// A record that an event fired an alert. The audit trail of "this event
/// fired this alert". A <c>Match</c> is unique per <c>(AlertId, EventId)</c>
/// — the dispatcher relies on this to be idempotent under retries
/// (<c>1-features.md</c> §6 reliability rule).
/// </summary>
public class Match
{
    public Guid Id { get; set; }

    public Guid AlertId { get; set; }

    public Guid EventId { get; set; }

    /// <summary>UTC time the matcher emitted the row.</summary>
    public DateTimeOffset FiredAt { get; set; } = DateTimeOffset.UtcNow;
}

using SonrisaNews.Domain;

namespace SonrisaNews.Domain.Entities;

/// <summary>
/// The actual delivery record: a Match routed to a Channel in a particular
/// <see cref="DeliveryMode"/>. The activity feed reads this table; the cleanup
/// service prunes it after 30 days (1-features.md §6 retention).
/// </summary>
public class Notification
{
    public Guid Id { get; set; }

    public Guid UserId { get; set; }

    public Guid AlertId { get; set; }

    public Guid MatchId { get; set; }

    public Guid ChannelId { get; set; }

    public DeliveryMode Mode { get; set; }

    /// <summary>Lifecycle: <c>Pending → Sent | Failed</c>. Other states are reserved for digest batching (wave 8).</summary>
    public string Status { get; set; } = "Pending";

    public DateTimeOffset? SentAt { get; set; }

    /// <summary>Last delivery error. Cleared on a successful retry.</summary>
    public string? Error { get; set; }

    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;
}

using SonrisaNews.Domain;

namespace SonrisaNews.Domain.Entities;

/// <summary>
/// An admin-curated upstream (an RSS feed, a market symbol group, a disaster
/// feed). The poller iterates <c>Enabled = true</c> rows. The
/// <see cref="Config"/> JSON holds the type-specific source config
/// (e.g. the feed URL for an RSS source).
/// </summary>
public class Source
{
    public Guid Id { get; set; }

    public SourceType Type { get; set; }

    /// <summary>Admin-displayed label (e.g. <c>Reuters World</c>).</summary>
    public string Name { get; set; } = string.Empty;

    /// <summary>Type-specific configuration as a JSON string. Stored as <c>TEXT</c> on SQLite, <c>jsonb</c> on Postgres.</summary>
    public string Config { get; set; } = "{}";

    /// <summary>Master switch. False = the poller skips this source.</summary>
    public bool Enabled { get; set; } = true;

    public DateTimeOffset? LastFetchedAt { get; set; }

    /// <summary>Last fetch error message. Cleared on a successful fetch.</summary>
    public string? LastError { get; set; }

    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;
}

namespace SonrisaNews.Domain.Entities;

/// <summary>
/// Opaque refresh token issued at sign-in, stored hashed. The auth flow
/// rotates refresh tokens on every use (<c>ReplacedById</c>); revoking a
/// refresh sets <see cref="RevokedAt"/>.
/// </summary>
public class RefreshToken
{
    public Guid Id { get; set; }

    public Guid UserId { get; set; }

    /// <summary>Hashed token value. The plaintext only ever lives in the httpOnly cookie.</summary>
    public string TokenHash { get; set; } = string.Empty;

    public DateTimeOffset ExpiresAt { get; set; }

    public DateTimeOffset? RevokedAt { get; set; }

    /// <summary>The id of the refresh token that replaced this one on rotation. Null if this token was never rotated.</summary>
    public Guid? ReplacedById { get; set; }

    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;
}

using SonrisaNews.Domain;

namespace SonrisaNews.Domain.Entities;

/// <summary>
/// Join row binding an <see cref="Alert"/> to a <see cref="Channel"/> with a
/// <see cref="DeliveryMode"/>. The (AlertId, ChannelId) pair is the primary
/// key — the channel-mode matrix is unique per row.
/// </summary>
public class AlertChannelMode
{
    public Guid AlertId { get; set; }
    public Guid ChannelId { get; set; }

    public DeliveryMode Mode { get; set; } = DeliveryMode.Realtime;

    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;
}

using SonrisaNews.Domain;

namespace SonrisaNews.Domain.Entities;

/// <summary>
/// A person who signs in to Sonrisa News. The entity is the root of the domain;
/// channels, alerts, notifications, and audit log entries all reference a User.
/// </summary>
/// <remarks>
/// Field set is the MVP minimum from <c>docs/roadmap/1-features.md</c> §4.
/// Wave 3 (auth) wires ASP.NET Core Identity and JWT; the password hash column
/// is what the identity store will use. Wave 8 (cleanup) reads
/// <see cref="DeletedAt"/> to enforce the 30-day soft-delete grace period.
/// </remarks>
public class User
{
    public Guid Id { get; set; }

    /// <summary>Email used for sign-in and notifications. Unique, case-insensitive.</summary>
    public string Email { get; set; } = string.Empty;

    /// <summary>Argon2id hash of the user's password. Never stored in plaintext.</summary>
    public string PasswordHash { get; set; } = string.Empty;

    /// <summary>User-chosen display name. Falls back to the local part of the email for anonymous mentions.</summary>
    public string DisplayName { get; set; } = string.Empty;

    /// <summary>RBAC role. Drives authorization checks. Seeded from <c>rbac_policy.csv</c>.</summary>
    public UserRole Role { get; set; } = UserRole.User;

    /// <summary>IANA time-zone id (e.g. <c>Europe/Budapest</c>). Used to render digest times in the user's local clock.</summary>
    public string TimeZone { get; set; } = "UTC";

    /// <summary>Account lifecycle state. New users land in <see cref="UserStatus.PendingEmailVerification"/>.</summary>
    public UserStatus Status { get; set; } = UserStatus.PendingEmailVerification;

    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;

    public DateTimeOffset? UpdatedAt { get; set; }

    /// <summary>UTC timestamp at which the user (or an admin) requested deletion. Null = active. Hard-delete happens 30 days later (wave 8 cleanup).</summary>
    public DateTimeOffset? DeletedAt { get; set; }
}

using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SonrisaNews.Domain.Entities;

namespace SonrisaNews.Infrastructure.Persistence.Configurations;

/// <summary>
/// EF Core mapping for <see cref="User"/>. The unique index on <see cref="User.Email"/>
/// is the only non-FK index the entity owns; FKs to <c>User</c> are declared on
/// the dependent side (alerts, channels, etc.).
/// </summary>
internal class UserConfiguration : IEntityTypeConfiguration<User>
{
    public void Configure(EntityTypeBuilder<User> builder)
    {
        builder.ToTable("Users");
        builder.HasKey(u => u.Id);

        builder.Property(u => u.Email)
            .IsRequired()
            .HasMaxLength(320);   // RFC 5321 SMTP path limit; covers the longest legal address.

        builder.Property(u => u.PasswordHash)
            .IsRequired()
            .HasMaxLength(512);   // Argon2id PHC string, with room for future params.

        builder.Property(u => u.DisplayName)
            .IsRequired()
            .HasMaxLength(120);

        builder.Property(u => u.TimeZone)
            .IsRequired()
            .HasMaxLength(64);

        builder.Property(u => u.Role)
            .HasConversion<int>();

        builder.Property(u => u.Status)
            .HasConversion<int>();

        builder.HasIndex(u => u.Email)
            .IsUnique()
            .HasDatabaseName("UX_Users_Email");
    }
}

using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SonrisaNews.Domain.Entities;

namespace SonrisaNews.Infrastructure.Persistence.Configurations;

/// <summary>
/// EF Core mapping for the <see cref="AlertChannelMode"/> join. The (AlertId,
/// ChannelId) pair is the primary key — that gives us the unique row per
/// (alert, channel) for free and is the index that backs the channel-mode
/// matrix read path.
/// </summary>
internal class AlertChannelModeConfiguration : IEntityTypeConfiguration<AlertChannelMode>
{
    public void Configure(EntityTypeBuilder<AlertChannelMode> builder)
    {
        builder.ToTable("AlertChannelModes");
        builder.HasKey(acm => new { acm.AlertId, acm.ChannelId });

        builder.Property(acm => acm.Mode)
            .HasConversion<int>();
    }
}

