    private static string LocateInfrastructureProjectDirectory()
    {
        // Walk up from the current directory until we find the
        // SonrisaNews.Infrastructure.csproj marker. The EF tool starts in
        // the operator's CWD (typically the repo root); the appsettings live
        // one level inside src/SonrisaNews.Infrastructure.
        var directory = new DirectoryInfo(Directory.GetCurrentDirectory());
        while (directory is not null)
        {
            var candidate = Path.Combine(directory.FullName, "src", "SonrisaNews.Infrastructure");
            if (Directory.Exists(candidate) && File.Exists(Path.Combine(candidate, "SonrisaNews.Infrastructure.csproj")))
            {
                return candidate;
            }

            // Allow running the EF tool from inside the Infrastructure
            // project too (some workflows do this).
            if (File.Exists(Path.Combine(directory.FullName, "SonrisaNews.Infrastructure.csproj")))
            {
                return directory.FullName;
            }

            directory = directory.Parent;
        }

        // Fallback to the current directory so the operator sees the same
        // "missing config" error they'd see from the runtime host.
        return Directory.GetCurrentDirectory();
