/// Wave 2 — covers the <c>AddSonrisaNewsDbContext</c> DI path. Round 3 of
/// the wave-2 implementer cycle surfaced a missing <c>using</c> on the
/// design-time factory; the runtime registration has the same shape, so the
/// two should not drift. These tests fail if the relative-path resolution
/// or the default fallback changes silently.
/// </summary>
[Trait("Category", DatabaseTestCategory.Database)]
public class SonrisaNewsDbContextRegistrationTests : IDisposable
{
    private readonly string _scratchRoot;

    public SonrisaNewsDbContextRegistrationTests()
    {
        _scratchRoot = Path.Combine(Path.GetTempPath(), "sonrisa-di-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(_scratchRoot);
        File.WriteAllText(Path.Combine(_scratchRoot, "AGENTS.md"), "# scratch");
    }

    public void Dispose()
    {
        try { Directory.Delete(_scratchRoot, recursive: true); } catch (IOException) { }
        try { Directory.Delete(Path.Combine(_scratchRoot, PathConstants.DataDirectory), recursive: true); } catch (IOException) { }
        GC.SuppressFinalize(this);
    }

    [Fact]
    public void AddSonrisaNewsDbContext_ResolvesBlankConnectionString_ToAbsoluteDevPath()
    {
        // The "no config" fallback must always anchor to the repo root, not
        // to whatever CWD the host happened to launch from. We assert by
        // building a service provider from the scratch root and reading the
        // configured connection string off the resolved context.
        var services = new ServiceCollection();
        services.AddSingleton<IConfiguration>(new ConfigurationBuilder()
            .AddInMemoryCollection(new Dictionary<string, string?>())
            .Build());
        services.AddSonrisaNewsDbContext();
        services.AddLogging();

        using var sp = services.BuildServiceProvider();
        using var ctx = sp.GetRequiredService<SonrisaNewsDbContext>();

        var connectionString = ctx.Database.GetConnectionString();
        connectionString.Should().StartWith("Data Source=");
        var dataSource = connectionString["Data Source=".Length..];

        Path.IsPathRooted(dataSource).Should().BeTrue(
            "the blank-config fallback must resolve to an absolute path so the SQLite file is the same regardless of CWD");
        dataSource.Should().Be(Path.Combine(_scratchRoot, PathConstants.DataDirectory, PathConstants.SonrisaDatabaseFileName));
    }

    [Fact]
    public void AddSonrisaNewsDbContext_ResolvesRelativeConnectionString_AgainstRepoRoot()
    {
        // The relative-path branch in the registration. With appsettings
        // setting a `Data Source=relative/sonrisa.db`, the resolved
        // connection string must end up under the repo root, not under
        // whatever CWD the test process happens to be in.
        var services = new ServiceCollection();
        services.AddSingleton<IConfiguration>(new ConfigurationBuilder()
            .AddInMemoryCollection(new Dictionary<string, string?>
            {
                ["ConnectionStrings:Sonrisa"] = "Data Source=relative/sonrisa.db",
            })
            .Build());
        services.AddSonrisaNewsDbContext();
        services.AddLogging();

        using var sp = services.BuildServiceProvider();
        using var ctx = sp.GetRequiredService<SonrisaNewsDbContext>();

        var dataSource = ctx.Database.GetConnectionString()!["Data Source=".Length..];
        Path.IsPathRooted(dataSource).Should().BeTrue();
        dataSource.Should().Be(Path.Combine(_scratchRoot, "relative", "sonrisa.db").Replace('/', Path.DirectorySeparatorChar));
    }
}

